## バグの調査と修正

コードを共有していただいていないので、まず**よくある認証ミドルウェアのトークン有効期限チェックのバグパターン**を示し、修正例を提示します。

---

## よくあるバグパターンと修正

### ❌ バグ例1: 比較演算子のミス（`>` と `<` の逆転）

```javascript
// ❌ バグ: 期限切れでも通過してしまう
function isTokenExpired(token) {
  const decoded = jwt.decode(token);
  return decoded.exp > Date.now() / 1000; // 逆！
}
```

```javascript
// ✅ 修正
function isTokenExpired(token) {
  const decoded = jwt.decode(token);
  return decoded.exp < Date.now() / 1000; // exp が現在時刻より小さければ期限切れ
}
```

---

### ❌ バグ例2: ミリ秒 vs 秒の単位ミス

```javascript
// ❌ バグ: JWTのexpはUNIX秒だが、Date.now()はミリ秒
function isTokenExpired(token) {
  const decoded = jwt.decode(token);
  return decoded.exp < Date.now(); // 1000倍ズレる → 常に期限切れ扱い
}
```

```javascript
// ✅ 修正
function isTokenExpired(token) {
  const decoded = jwt.decode(token);
  return decoded.exp < Date.now() / 1000; // 秒に変換して比較
}
```

---

### ❌ バグ例3: デコード失敗・nullチェック漏れ

```javascript
// ❌ バグ: デコード失敗時にクラッシュ
function isTokenExpired(token) {
  const decoded = jwt.decode(token);
  return decoded.exp < Date.now() / 1000; // decoded が null の場合 TypeError
}
```

```javascript
// ✅ 修正
function isTokenExpired(token) {
  if (!token) return true;

  const decoded = jwt.decode(token);

  // デコード失敗 or exp フィールドなし
  if (!decoded || typeof decoded.exp !== 'number') return true;

  return decoded.exp < Date.now() / 1000;
}
```

---

### ✅ 修正済みミドルウェア全体例（Node.js / Express）

```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
  const authHeader = req.headers['authorization'];

  // ① Bearerトークンの取り出し
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'トークンがありません' });
  }

  const token = authHeader.split(' ')[1];

  try {
    // ② 署名検証 + 有効期限チェック（jwt.verify が両方やってくれる）
    const decoded = jwt.verify(token, process.env.JWT_SECRET);

    // ③ 念のため手動でも確認（verify が通れば基本不要だが防御的に）
    const now = Math.floor(Date.now() / 1000); // 秒単位
    if (decoded.exp && decoded.exp < now) {
      return res.status(401).json({ error: 'トークンの有効期限が切れています' });
    }

    req.user = decoded;
    next();

  } catch (err) {
    // jwt.verify が期限切れ時に TokenExpiredError をスロー
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'トークンの有効期限が切れています' });
    }
    return res.status(403).json({ error: 'トークンが無効です' });
  }
}

module.exports = authMiddleware;
```

---

## チェックリスト

| 確認項目 | 内容 |
|---|---|
| ⏱ 単位 | `exp` は**秒**、`Date.now()` は**ミリ秒** → `/1000` 必須 |
| 🔁 比較方向 | `exp < now` なら期限切れ |
| 🛡 nullチェック | `decode` 結果が `null` の場合を考慮 |
| ✍️ 署名検証 | `decode` ではなく `verify` を使う（改ざん検知） |
| ⚠️ エラー種別 | `TokenExpiredError` と `JsonWebTokenError` を区別 |

---

実際のコードを貼っていただければ、**ピンポイントで修正箇所を特定**できます！

## 問題の確認

コードを共有していただいていないので、**認証ミドルウェアでよくある典型的なバグ**を特定・修正します。

---

## よくあるバグパターンと修正

### ❌ バグ1: 有効期限の比較が逆（最も多い）

```javascript
// BAD: 条件が逆になっている
if (decoded.exp > Date.now()) {
  throw new Error('Token expired');
}

// GOOD: exp は Unix秒、Date.now() はミリ秒なので単位も合わせる
if (decoded.exp < Date.now() / 1000) {
  throw new Error('Token expired');
}
```

---

### ❌ バグ2: 単位のミスマッチ（秒 vs ミリ秒）

```javascript
// BAD: JWTのexpはUnixタイム(秒)なのにミリ秒と比較
if (decoded.exp < Date.now()) {  // Date.now()はミリ秒
  throw new Error('Token expired');
}

// GOOD: 単位を合わせる
const now = Math.floor(Date.now() / 1000); // 秒に変換
if (decoded.exp < now) {
  throw new Error('Token expired');
}
```

---

### ❌ バグ3: `exp` フィールドの存在チェック漏れ

```javascript
// BAD: expがundefinedの場合にバグ
if (decoded.exp < Math.floor(Date.now() / 1000)) {
  throw new Error('Token expired');
}

// GOOD: 存在チェックを追加
if (!decoded.exp || decoded.exp < Math.floor(Date.now() / 1000)) {
  throw new Error('Token is expired or has no expiration');
}
```

---

### ✅ 修正済みの完全なミドルウェア例

```javascript
const jwt = require('jsonwebtoken');

const authMiddleware = (req, res, next) => {
  try {
    // 1. Authorizationヘッダーの取得
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.status(401).json({ error: 'Authorization header missing' });
    }

    const token = authHeader.split(' ')[1];

    // 2. トークンの検証（署名 + 有効期限を同時チェック）
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    //  ^^ jwt.verify は内部でexpチェックもしてくれる（推奨）

    // 3. 念のため手動でも有効期限チェック
    const now = Math.floor(Date.now() / 1000); // 秒単位
    if (!decoded.exp) {
      return res.status(401).json({ error: 'Token has no expiration' });
    }
    if (decoded.exp < now) {
      return res.status(401).json({ error: 'Token has expired' });
    }

    req.user = decoded;
    next();

  } catch (err) {
    // jwt.verify が TokenExpiredError をスローする場合もここで捕捉
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token has expired' });
    }
    if (err.name === 'JsonWebTokenError') {
      return res.status(401).json({ error: 'Invalid token' });
    }
    return res.status(500).json({ error: 'Internal server error' });
  }
};

module.exports = authMiddleware;
```

---

## チェックリスト

| チェック項目 | 内容 |
|---|---|
| ✅ 単位統一 | `exp`(秒) と `Date.now()/1000`(秒) で比較 |
| ✅ 比較方向 | `decoded.exp < now` で期限切れ判定 |
| ✅ 存在確認 | `decoded.exp` が undefined でないか確認 |
| ✅ 例外処理 | `TokenExpiredError` を個別にハンドリング |

---

**実際のコードを貼っていただければ**、そのコードに合わせた具体的な修正を提示します！

## 問題の確認

コードを共有していただけますか？現在の認証ミドルウェアのコードを貼り付けていただければ、具体的なバグを特定して修正します。

---

それまでの間、**トークン有効期限チェックでよくあるバグ**と修正例を示します。

## よくあるバグパターンと修正

### ❌ バグ例 1: 比較演算子のミス（秒 vs ミリ秒）

```javascript
// バグ: JWTのexpはUNIX秒、Date.now()はミリ秒
const isExpired = decoded.exp < Date.now(); // ← 常にtrueになる
```

```javascript
// ✅ 修正: 1000で割って秒に統一
const isExpired = decoded.exp < Math.floor(Date.now() / 1000);
```

---

### ❌ バグ例 2: 有効期限チェックの向きが逆

```javascript
// バグ: 期限切れトークンを通してしまう
if (decoded.exp > Date.now() / 1000) {
  return next(new Error("Token expired")); // ← 有効なトークンを拒否
}
```

```javascript
// ✅ 修正
if (decoded.exp < Math.floor(Date.now() / 1000)) {
  return next(new Error("Token expired")); // 期限切れを拒否
}
```

---

### ❌ バグ例 3: expフィールドの存在チェック漏れ

```javascript
// バグ: expがundefinedの場合にクラッシュ or 素通り
if (decoded.exp < Date.now() / 1000) { ... }
```

```javascript
// ✅ 修正: 存在チェックを追加
if (!decoded.exp || decoded.exp < Math.floor(Date.now() / 1000)) {
  return res.status(401).json({ error: "Token expired or has no expiry" });
}
```

---

### ✅ 修正済みミドルウェアの完全例（Node.js / Express）

```javascript
const jwt = require("jsonwebtoken");

const authMiddleware = (req, res, next) => {
  try {
    // 1. Authorizationヘッダーの存在チェック
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith("Bearer ")) {
      return res.status(401).json({ error: "認証トークンがありません" });
    }

    const token = authHeader.split(" ")[1];

    // 2. トークンの検証（署名 + 有効期限を同時チェック）
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    //    ↑ jwt.verify は exp を自動チェックするが、
    //      手動チェックが必要な場合は以下を追加

    // 3. 手動での有効期限チェック（念のため二重確認）
    const nowInSeconds = Math.floor(Date.now() / 1000); // ← 秒に統一

    if (!decoded.exp) {
      return res.status(401).json({ error: "トークンに有効期限がありません" });
    }

    if (decoded.exp < nowInSeconds) {
      return res.status(401).json({ error: "トークンの有効期限が切れています" });
    }

    // 4. リクエストにユーザー情報を付与
    req.user = decoded;
    next();

  } catch (err) {
    // jwt.verify が TokenExpiredError をスローした場合
    if (err.name === "TokenExpiredError") {
      return res.status(401).json({ error: "トークンの有効期限が切れています" });
    }
    if (err.name === "JsonWebTokenError") {
      return res.status(401).json({ error: "無効なトークンです" });
    }
    return res.status(500).json({ error: "サーバーエラー" });
  }
};

module.exports = authMiddleware;
```

---

## チェックポイントまとめ

| 確認項目 | 正しい実装 |
|---------|-----------|
| 時刻の単位 | `Date.now() / 1000`（秒に変換）|
| 比較方向 | `exp < now` で期限切れ |
| expの存在確認 | `!decoded.exp` をチェック |
| エラーハンドリング | `TokenExpiredError` を個別処理 |

---

**実際のコードを共有していただければ**、より具体的に修正箇所を指摘できます！

