## よくあるバグと修正

### ❌ バグのあるコード（よくあるパターン）

```javascript
// バグ1: 符号の間違い（期限切れを正常と判定）
if (token.exp < Date.now()) {
  return next(); // 期限切れなのに通過させてしまう
}

// バグ2: 単位ミス（JWTのexpは秒、Date.now()はミリ秒）
if (token.exp < Date.now()) {
  throw new Error("Token expired");
}

// バグ3: 未来日時チェックの欠如
if (!token.exp) {
  return next(); // expがない場合をスルー
}
```

### ✅ 修正後

```javascript
function authMiddleware(req, res, next) {
  try {
    const authHeader = req.headers.authorization;
    if (!authHeader?.startsWith("Bearer ")) {
      return res.status(401).json({ error: "No token provided" });
    }

    const token = jwt.verify(authHeader.split(" ")[1], process.env.JWT_SECRET);

    // ✅ expの存在確認
    if (!token.exp) {
      return res.status(401).json({ error: "Token has no expiration" });
    }

    // ✅ 単位を秒に統一して比較
    const nowInSeconds = Math.floor(Date.now() / 1000);

    // ✅ 正しい比較（expが現在時刻より小さければ期限切れ）
    if (token.exp < nowInSeconds) {
      return res.status(401).json({ error: "Token expired" });
    }

    // ✅ 未来すぎるトークンも拒否（オプション）
    const MAX_FUTURE_SECONDS = 60 * 60 * 24 * 30; // 30日
    if (token.exp > nowInSeconds + MAX_FUTURE_SECONDS) {
      return res.status(401).json({ error: "Token expiration too far in future" });
    }

    req.user = token;
    next();
  } catch (err) {
    // jwt.verify が期限切れを検出した場合も処理
    if (err.name === "TokenExpiredError") {
      return res.status(401).json({ error: "Token expired" });
    }
    return res.status(401).json({ error: "Invalid token" });
  }
}
```

---

## チェックポイント

| 確認項目 | 正しい実装 |
|---------|-----------|
| 時刻単位 | `Date.now() / 1000`（秒に変換） |
| 比較演算子 | `token.exp < now` で期限切れ |
| expの存在確認 | `if (!token.exp)` でガード |
| エラーハンドリング | `TokenExpiredError` を個別キャッチ |

---

