# Node.jsでPostgreSQLのコネクションプーリングをセットアップする方法

## 主要なライブラリの比較

| ライブラリ | 特徴 | 用途 |
|-----------|------|------|
| `pg` (node-postgres) | 軽量・シンプル | 基本的な用途 |
| `pg-pool` | pgの公式プール実装 | 本番環境向け |
| `knex` | クエリビルダー付き | 複雑なクエリ |
| `prisma` | フルORM | 大規模開発 |

---

## 方法1: pg + Pool（推奨・最もシンプル）

### インストール

```bash
npm install pg
npm install dotenv  # 環境変数管理
```

### 基本セットアップ

```javascript
// db/pool.js
const { Pool } = require('pg');
require('dotenv').config();

const pool = new Pool({
  host:     process.env.DB_HOST,
  port:     process.env.DB_PORT || 5432,
  database: process.env.DB_NAME,
  user:     process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // プール設定
  max: 20,                // 最大コネクション数（デフォルト: 10）
  min: 2,                 // 最小コネクション数
  idleTimeoutMillis: 30000,    // アイドル時のタイムアウト（30秒）
  connectionTimeoutMillis: 2000, // コネクション取得タイムアウト（2秒）
  maxUses: 7500,          // コネクションの最大再利用回数
});

// エラーハンドリング（重要！）
pool.on('error', (err, client) => {
  console.error('予期しないクライアントエラー:', err);
  process.exit(-1);
});

module.exports = pool;
```

### 環境変数ファイル

```bash
# .env
DB_HOST=localhost
DB_PORT=5432
DB_NAME=mydb
DB_USER=myuser
DB_PASSWORD=mypassword
```

---

## 方法2: 接続URLを使った設定

```javascript
// db/pool.js
const { Pool } = require('pg');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  // SSL設定（本番環境・Heroku等）
  ssl: process.env.NODE_ENV === 'production'
    ? { rejectUnauthorized: false }
    : false,
  max: 20,
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 2000,
});

module.exports = pool;
```

```bash
# .env
DATABASE_URL=postgresql://myuser:mypassword@localhost:5432/mydb
```

---

## 実際の使い方

### パターン1: シンプルなクエリ（自動コネクション管理）

```javascript
// services/userService.js
const pool = require('../db/pool');

// ✅ poolを直接使う（コネクションの取得・解放を自動管理）
async function getAllUsers() {
  try {
    const result = await pool.query('SELECT * FROM users ORDER BY id');
    return result.rows;
  } catch (err) {
    console.error('クエリエラー:', err);
    throw err;
  }
}

async function getUserById(id) {
  const result = await pool.query(
    'SELECT * FROM users WHERE id = $1',  // $1でSQLインジェクション対策
    [id]
  );
  return result.rows[0];
}

async function createUser(name, email) {
  const result = await pool.query(
    'INSERT INTO users (name, email) VALUES ($1, $2) RETURNING *',
    [name, email]
  );
  return result.rows[0];
}
```

### パターン2: トランザクション（手動コネクション管理）

```javascript
// services/transferService.js
const pool = require('../db/pool');

async function transferMoney(fromId, toId, amount) {
  // ⚠️ トランザクションは必ず1つのクライアントで実行
  const client = await pool.connect();

  try {
    await client.query('BEGIN');

    // 残高確認
    const { rows } = await client.query(
      'SELECT balance FROM accounts WHERE id = $1 FOR UPDATE',
      [fromId]
    );

    if (rows[0].balance < amount) {
      throw new Error('残高不足');
    }

    // 引き落とし
    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId]
    );

    // 入金
    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId]
    );

    await client.query('COMMIT');
    console.log('送金完了');

  } catch (err) {
    await client.query('ROLLBACK');
    console.error('送金失敗、ロールバック実行:', err);
    throw err;
  } finally {
    client.release(); // ✅ 必ずコネクションを解放！
  }
}
```

---

## Expressと組み合わせる例

```javascript
// app.js
const express = require('express');
const pool = require('./db/pool');
const app = express();

app.use(express.json());

// ユーザー一覧取得
app.get('/users', async (req, res) => {
  try {
    const result = await pool.query('SELECT * FROM users');
    res.json(result.rows);
  } catch (err) {
    res.status(500).json({ error: 'データベースエラー' });
  }
});

// ユーザー作成
app.post('/users', async (req, res) => {
  const { name, email } = req.body;
  try {
    const result = await pool.query(
      'INSERT INTO users (name, email) VALUES ($1, $2) RETURNING *',
      [name, email]
    );
    res.status(201).json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: 'データベースエラー' });
  }
});

// アプリ終了時にプールを閉じる
process.on('SIGINT', async () => {
  await pool.end();
  console.log('プール終了');
  process.exit(0);
});

app.listen(3000, () => console.log('サーバー起動: http://localhost:3000'));
```

---

## コネクション数の目安

```javascript
// 適切なmax値の計算目安
// PostgreSQLの最大接続数（デフォルト100） ÷ アプリのインスタンス数

// 例: PostgreSQL最大100, アプリ5インスタンスの場合
const pool = new Pool({
  max: 20,  // 100 ÷ 5 = 20
});
```

---

## よくあるミスと対策

```javascript
// ❌ 悪い例：コネクションリーク
async function badExample() {
  const client = await pool.connect();
  const result = await client.query('SELECT * FROM users');
  // release()を忘れた！→コネクションが枯渇する
  return result.rows;
}

// ✅ 良い例：finallyで確実に解放
async function goodExample() {
  const client = await pool.connect();
  try {
    const result = await client.query('SELECT * FROM users');
    return result.rows;
  } finally {
    client.release(); // エラーが発生しても必ず実行される
  }
}

// ✅ さらに良い例：トランザクション不要ならpoolを直接使う
async function bestExample() {
  const result = await pool.query('SELECT * FROM users');
  return result.rows; // 自動でコネクション管理してくれる
}
```

---

## ヘルスチェック機能の追加

```javascript
// db/pool.js に追加
async function checkConnection() {
  try {
    const client = await pool.connect();
    await client.query('SELECT 1');
    client.release();
    console.log('✅ データベース接続成功');
    return true;
  } catch (err) {
    console.error('❌ データベース接続失敗:', err);
    return false;
  }
}

module.exports = { pool, checkConnection };

// アプリ起動時に確認
// app.js
const { pool, checkConnection } = require('./db/pool');
checkConnection();
```

---

## まとめ

```
シングルクエリ  → pool.query() を直接使用（自動管理）
トランザクション → pool.connect() → try/finally → client.release()
本番環境       → max: 20前後, SSL設定, エラーハンドリング必須
```

基本的には **`pool.query()`を直接使う**方法が最もシンプルで安全です。トランザクションが必要な場合のみ`client`を手動取得し、**必ず`release()`を呼ぶ**ことがポイントです！

# Node.jsでPostgreSQLのコネクションプーリング設定

## 主要なライブラリの選択肢

| ライブラリ | 特徴 |
|-----------|------|
| `pg` (node-postgres) | 最も一般的、`Pool`クラス内蔵 |
| `pg-pool` | `pg`のPool部分を独立させたもの |
| `knex` | クエリビルダー + プーリング |
| `sequelize` | ORM + プーリング |

---

## 1. 基本セットアップ（pg ライブラリ）

### インストール

```bash
npm install pg
npm install dotenv  # 環境変数管理
```

### 環境変数設定（.env）

```env
DB_HOST=localhost
DB_PORT=5432
DB_NAME=mydb
DB_USER=myuser
DB_PASSWORD=mypassword
DB_MAX_CONNECTIONS=20
DB_IDLE_TIMEOUT=30000
DB_CONNECTION_TIMEOUT=2000
```

---

## 2. プール設定ファイル

```javascript
// src/db/pool.js
const { Pool } = require('pg');
require('dotenv').config();

const pool = new Pool({
  host:     process.env.DB_HOST,
  port:     parseInt(process.env.DB_PORT, 10),
  database: process.env.DB_NAME,
  user:     process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // ── プーリング設定 ──────────────────────────
  max:             20,    // 最大コネクション数（デフォルト: 10）
  min:              2,    // 最小コネクション数
  idleTimeoutMillis:    30000, // アイドル状態のコネクションを閉じるまでの時間（ms）
  connectionTimeoutMillis: 2000, // 接続タイムアウト（ms）
  maxUses:        7500,   // コネクション再利用の最大回数（メモリリーク対策）

  // ── SSL設定（本番環境向け） ──────────────────
  ssl: process.env.NODE_ENV === 'production'
    ? { rejectUnauthorized: false }
    : false,
});

// ── イベントハンドラ ────────────────────────────
pool.on('connect', (client) => {
  console.log('🟢 新しいコネクションがプールに追加されました');
});

pool.on('acquire', (client) => {
  console.log('📌 コネクションがプールから取得されました');
});

pool.on('remove', (client) => {
  console.log('🔴 コネクションがプールから削除されました');
});

pool.on('error', (err, client) => {
  console.error('❌ プールでエラーが発生しました:', err.message);
  process.exit(-1); // 致命的エラーの場合はプロセスを終了
});

module.exports = pool;
```

---

## 3. データベース操作ヘルパー

```javascript
// src/db/query.js
const pool = require('./pool');

/**
 * シンプルなクエリ実行
 */
const query = async (text, params) => {
  const start = Date.now();
  try {
    const result = await pool.query(text, params);
    const duration = Date.now() - start;
    console.log(`✅ クエリ実行完了 | 時間: ${duration}ms | 行数: ${result.rowCount}`);
    return result;
  } catch (error) {
    console.error('❌ クエリエラー:', error.message);
    throw error;
  }
};

/**
 * トランザクション処理
 */
const withTransaction = async (callback) => {
  const client = await pool.connect(); // プールからコネクションを取得
  try {
    await client.query('BEGIN');
    const result = await callback(client);
    await client.query('COMMIT');
    return result;
  } catch (error) {
    await client.query('ROLLBACK');
    console.error('🔄 ロールバックしました:', error.message);
    throw error;
  } finally {
    client.release(); // 必ずプールに返却する
  }
};

/**
 * プールの状態確認
 */
const getPoolStatus = () => ({
  total:   pool.totalCount,   // 総コネクション数
  idle:    pool.idleCount,    // アイドル中のコネクション数
  waiting: pool.waitingCount, // 待機中のリクエスト数
});

module.exports = { query, withTransaction, getPoolStatus };
```

---

## 4. 実際の使用例

```javascript
// src/users/userService.js
const { query, withTransaction } = require('../db/query');

// ── 単純なSELECT ───────────────────────────────
const getUserById = async (id) => {
  const { rows } = await query(
    'SELECT id, name, email FROM users WHERE id = $1',
    [id]
  );
  return rows[0] ?? null;
};

// ── INSERT ────────────────────────────────────
const createUser = async (name, email) => {
  const { rows } = await query(
    'INSERT INTO users (name, email) VALUES ($1, $2) RETURNING *',
    [name, email]
  );
  return rows[0];
};

// ── トランザクションを使った複数操作 ──────────────
const transferPoints = async (fromId, toId, points) => {
  return await withTransaction(async (client) => {
    // 送り元の残高確認
    const { rows: [sender] } = await client.query(
      'SELECT points FROM users WHERE id = $1 FOR UPDATE',
      [fromId]
    );

    if (sender.points < points) {
      throw new Error('ポイントが不足しています');
    }

    // 送り元から減算
    await client.query(
      'UPDATE users SET points = points - $1 WHERE id = $2',
      [points, fromId]
    );

    // 受け取り先に加算
    await client.query(
      'UPDATE users SET points = points + $1 WHERE id = $2',
      [points, toId]
    );

    // 履歴を記録
    await client.query(
      'INSERT INTO point_history (from_id, to_id, points) VALUES ($1, $2, $3)',
      [fromId, toId, points]
    );

    return { success: true, transferred: points };
  });
};

module.exports = { getUserById, createUser, transferPoints };
```

