## 5. アプリケーションの起動・終了処理

```javascript
// src/app.js
const express = require('express');
const pool = require('./db/pool');
const { getPoolStatus } = require('./db/query');

const app = express();

// ── ヘルスチェックエンドポイント ────────────────
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1'); // DB接続確認
    res.json({
      status: 'ok',
      pool: getPoolStatus(),
    });
  } catch (error) {
    res.status(503).json({ status: 'error', message: error.message });
  }
});

// ── グレースフルシャットダウン ──────────────────
const gracefulShutdown = async (signal) => {
  console.log(`\n${signal} を受信。シャットダウンします...`);
  try {
    await pool.end(); // プール内の全コネクションを閉じる
    console.log('✅ DBプールを正常にクローズしました');
    process.exit(0);
  } catch (error) {
    console.error('❌ シャットダウン中にエラー:', error);
    process.exit(1);
  }
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT',  () => gracefulShutdown('SIGINT'));

app.listen(3000, () => console.log('🚀 サーバー起動: http://localhost:3000'));
```

