## 6. プールサイズの目安

```
適切な max 値 = (コア数 × 2) + ストレージI/O数

例: 4コアのサーバー → max: 10〜20 が目安
```

| 環境 | 推奨設定 |
|------|---------|
| 開発環境 | `max: 5` |
| 本番（小規模） | `max: 10〜20` |
| 本番（大規模） | `max: 20〜50`（PgBouncerと併用推奨） |

---

## 7. よくあるミス ⚠️

```javascript
// ❌ NG: client.release()を忘れるとコネクションリーク！
const client = await pool.connect();
const result = await client.query('SELECT * FROM users');
// release() を呼び忘れ → プールが枯渇する

// ✅ OK: try/finally で必ず返却する
const client = await pool.connect();
try {
  const result = await client.query('SELECT * FROM users');
  return result.rows;
} finally {
  client.release(); // 必ず実行される
}
```

---

## まとめ

1. **`pool.query()`** → シンプルなクエリに使用（自動でコネクションを返却）
2. **`pool.connect()` + `client.release()`** → トランザクションなど複数クエリを同一コネクションで実行
3. **`pool.end()`** → アプリ終了時に必ず呼ぶ
4. 大規模環境では **PgBouncer** との組み合わせを検討する

# Node.jsでPostgreSQLのコネクションプーリングをセットアップする方法

## 主要なライブラリの選択肢

| ライブラリ | 特徴 |
|-----------|------|
| **pg (node-postgres)** | 最も一般的、軽量 |
| **pg-pool** | pgの公式プーリング拡張 |
| **knex** | クエリビルダー + プーリング |
| **Sequelize** | ORM + プーリング |

---

## 1. 基本セットアップ（pg + pg-pool）

### インストール

```bash
npm install pg
```

### 基本的なプール設定

```javascript
// db/pool.js
const { Pool } = require('pg');

const pool = new Pool({
  host: process.env.DB_HOST || 'localhost',
  port: process.env.DB_PORT || 5432,
  database: process.env.DB_NAME || 'mydb',
  user: process.env.DB_USER || 'postgres',
  password: process.env.DB_PASSWORD || 'password',

  // プーリング設定
  max: 20,                  // 最大コネクション数（デフォルト: 10）
  min: 2,                   // 最小コネクション数
  idleTimeoutMillis: 30000, // アイドル接続を切断するまでの時間(ms)
  connectionTimeoutMillis: 2000, // 接続タイムアウト(ms)
  maxUses: 7500,            // 1接続あたりの最大使用回数
});

// エラーハンドリング（必須）
pool.on('error', (err, client) => {
  console.error('予期しないエラーが発生しました', err);
  process.exit(-1);
});

module.exports = pool;
```

---

## 2. 使い方のパターン

### パターン① シンプルなクエリ（推奨）

```javascript
const pool = require('./db/pool');

async function getUsers() {
  try {
    // poolから自動でコネクションを取得・返却
    const result = await pool.query('SELECT * FROM users WHERE active = $1', [true]);
    return result.rows;
  } catch (err) {
    console.error('クエリエラー:', err);
    throw err;
  }
}
```

### パターン② クライアントを明示的に管理（トランザクション向け）

```javascript
const pool = require('./db/pool');

async function transferMoney(fromId, toId, amount) {
  // プールからクライアントを取得
  const client = await pool.connect();

  try {
    await client.query('BEGIN'); // トランザクション開始

    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId]
    );

    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId]
    );

    await client.query('COMMIT'); // コミット
    console.log('送金完了');

  } catch (err) {
    await client.query('ROLLBACK'); // エラー時はロールバック
    console.error('トランザクションエラー:', err);
    throw err;

  } finally {
    client.release(); // ⚠️ 必ずクライアントを返却する
  }
}
```

---

## 3. 環境変数を使った安全な設定

```bash
# .env
DB_HOST=localhost
DB_PORT=5432
DB_NAME=mydb
DB_USER=postgres
DB_PASSWORD=secret
DB_POOL_MAX=20
DB_POOL_MIN=2
DB_IDLE_TIMEOUT=30000
DB_CONNECTION_TIMEOUT=2000
```

```javascript
// db/pool.js
require('dotenv').config();
const { Pool } = require('pg');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL, // Heroku等で使用
  // または個別設定
  host: process.env.DB_HOST,
  port: parseInt(process.env.DB_PORT),
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  max: parseInt(process.env.DB_POOL_MAX) || 10,
  min: parseInt(process.env.DB_POOL_MIN) || 2,
  idleTimeoutMillis: parseInt(process.env.DB_IDLE_TIMEOUT) || 30000,
  connectionTimeoutMillis: parseInt(process.env.DB_CONNECTION_TIMEOUT) || 2000,

  // SSL設定（本番環境）
  ssl: process.env.NODE_ENV === 'production'
    ? { rejectUnauthorized: false }
    : false,
});

module.exports = pool;
```

---

## 4. ヘルパー関数でラップする

```javascript
// db/index.js
const pool = require('./pool');

const db = {
  // 通常のクエリ
  query: (text, params) => pool.query(text, params),

  // トランザクション用ヘルパー
  async transaction(callback) {
    const client = await pool.connect();
    try {
      await client.query('BEGIN');
      const result = await callback(client);
      await client.query('COMMIT');
      return result;
    } catch (err) {
      await client.query('ROLLBACK');
      throw err;
    } finally {
      client.release();
    }
  },

  // プール状態の確認
  getPoolStatus() {
    return {
      total: pool.totalCount,
      idle: pool.idleCount,
      waiting: pool.waitingCount,
    };
  },
};

module.exports = db;
```

```javascript
// 使用例
const db = require('./db');

// 通常クエリ
const users = await db.query('SELECT * FROM users');

// トランザクション
await db.transaction(async (client) => {
  await client.query('INSERT INTO orders ...');
  await client.query('UPDATE inventory ...');
});

// プール状態確認
console.log(db.getPoolStatus());
// { total: 5, idle: 3, waiting: 0 }
```

---

## 5. アプリ終了時のクリーンアップ

```javascript
// app.js
const pool = require('./db/pool');

// プロセス終了時にプールを閉じる
process.on('SIGINT', async () => {
  console.log('プールを終了中...');
  await pool.end();
  console.log('プール終了完了');
  process.exit(0);
});

process.on('SIGTERM', async () => {
  await pool.end();
  process.exit(0);
});
```

---

## 6. プールサイズの目安

```
適切なmax値 = データベースの最大接続数 ÷ アプリのインスタンス数

例: PostgreSQL最大接続数100、アプリ5台の場合
  max = 100 ÷ 5 = 20
```

| 環境 | max推奨値 |
|------|----------|
| 開発環境 | 5〜10 |
| 小規模本番 | 10〜20 |
| 大規模本番 | 20〜50 |

---

## よくある落とし穴 ⚠️

```javascript
// ❌ NGパターン: client.release()を忘れる
const client = await pool.connect();
const result = await client.query('SELECT 1');
// releaseを忘れるとコネクションが枯渇する！

// ✅ OKパターン: try/finally で必ず返却
const client = await pool.connect();
try {
  const result = await client.query('SELECT 1');
} finally {
  client.release(); // 必ず実行される
}
```

---

## まとめ

1. **`pool.query()`** → 単純なクエリはこれだけでOK
2. **`pool.connect()`** → トランザクションや複数クエリをまとめる場合
3. **`client.release()`** → `finally`ブロックで必ず実行
4. **環境変数** → 接続情報はコードに直書きしない
5. **プールサイズ** → DBの最大接続数を超えないよう設定

