# コールバック地獄をasync/awaitにリファクタリング

## Before: コールバック地獄

```javascript
// ユーザー情報を取得 → 注文履歴を取得 → 商品詳細を取得する例
function getUserOrderDetails(userId) {
  getUser(userId, function(err, user) {
    if (err) {
      console.error('ユーザー取得エラー:', err);
      return;
    }

    getOrders(user.id, function(err, orders) {
      if (err) {
        console.error('注文取得エラー:', err);
        return;
      }

      getProductDetails(orders[0].productId, function(err, product) {
        if (err) {
          console.error('商品取得エラー:', err);
          return;
        }

        getReviews(product.id, function(err, reviews) {
          if (err) {
            console.error('レビュー取得エラー:', err);
            return;
          }

          // ようやく全データが揃う
          console.log('ユーザー:', user.name);
          console.log('注文:', orders[0].id);
          console.log('商品:', product.name);
          console.log('レビュー数:', reviews.length);
        });
      });
    });
  });
}
```

---

## After: async/awaitでリファクタリング

```javascript
// 各関数をPromise化（既存のコールバック関数をラップ）
const getUserAsync    = (userId)    => new Promise((resolve, reject) =>
  getUser(userId, (err, data) => err ? reject(err) : resolve(data))
);
const getOrdersAsync  = (userId)    => new Promise((resolve, reject) =>
  getOrders(userId, (err, data) => err ? reject(err) : resolve(data))
);
const getProductAsync = (productId) => new Promise((resolve, reject) =>
  getProductDetails(productId, (err, data) => err ? reject(err) : resolve(data))
);
const getReviewsAsync = (productId) => new Promise((resolve, reject) =>
  getReviews(productId, (err, data) => err ? reject(err) : resolve(data))
);

// ✅ async/awaitで書き直し
async function getUserOrderDetails(userId) {
  try {
    const user    = await getUserAsync(userId);
    const orders  = await getOrdersAsync(user.id);
    const product = await getProductAsync(orders[0].productId);
    const reviews = await getReviewsAsync(product.id);

    console.log('ユーザー:', user.name);
    console.log('注文:',     orders[0].id);
    console.log('商品:',     product.name);
    console.log('レビュー数:', reviews.length);

    return { user, orders, product, reviews };

  } catch (err) {
    // エラーハンドリングを一箇所に集約
    console.error('データ取得エラー:', err);
    throw err;
  }
}

// 呼び出し
getUserOrderDetails('user-123');
```

---

## さらに改善: 並列実行できる処理は Promise.all でまとめる

```javascript
async function getUserOrderDetails(userId) {
  try {
    const user = await getUserAsync(userId);

    // 注文と関係ないデータは並列取得でパフォーマンスUP
    const orders = await getOrdersAsync(user.id);

    // 複数商品を並列取得
    const productIds = orders.map(order => order.productId);
    const [products, userProfile] = await Promise.all([
      Promise.all(productIds.map(id => getProductAsync(id))), // 商品を並列取得
      getUserProfileAsync(user.id),                           // プロフィールも並列取得
    ]);

    return { user, userProfile, orders, products };

  } catch (err) {
    console.error('データ取得エラー:', err);
    throw err;
  }
}
```

---

## 比較まとめ

| 観点 | コールバック地獄 | async/await |
|------|----------------|-------------|
| **可読性** | ❌ ネストが深い | ✅ 同期コードのように読める |
| **エラー処理** | ❌ 各階層で個別処理 | ✅ `try/catch` で一元管理 |
| **デバッグ** | ❌ スタックトレースが追いにくい | ✅ スタックトレースが明確 |
| **並列処理** | ❌ 複雑になりやすい | ✅ `Promise.all` で簡潔に |
| **保守性** | ❌ 変更が困難 | ✅ 追加・変更が容易 |

> **ポイント:** 既存のコールバック関数は `new Promise()` でラップするか、`util.promisify()`（Node.js）を使うと手軽にPromise化できます。

# コールバック地獄を async/await にリファクタリング

