## After: async/await にリファクタリング

```javascript
// ① コールバック関数を Promise でラップする（既存APIがコールバック形式の場合）
const getUserAsync      = (userId)   => new Promise((resolve, reject) =>
  getUser(userId, (err, data) => err ? reject(err) : resolve(data))
);
const getOrdersAsync    = (userId)   => new Promise((resolve, reject) =>
  getOrders(userId, (err, data) => err ? reject(err) : resolve(data))
);
const getOrderDetailsAsync = (orderId) => new Promise((resolve, reject) =>
  getOrderDetails(orderId, (err, data) => err ? reject(err) : resolve(data))
);
const getProductAsync   = (productId) => new Promise((resolve, reject) =>
  getProduct(productId, (err, data) => err ? reject(err) : resolve(data))
);

// ② async/await で書き直す
async function getUserOrderDetails(userId) {
  try {
    const user    = await getUserAsync(userId);
    console.log('ユーザー:', user.name);

    const orders  = await getOrdersAsync(user.id);
    console.log('注文数:', orders.length);

    const details = await getOrderDetailsAsync(orders[0].id);
    console.log('注文詳細:', details);

    const product = await getProductAsync(details.productId);
    console.log('商品名:', product.name);
    console.log('価格:', product.price);

    return { user, orders, details, product }; // まとめて返せる

  } catch (err) {
    // エラーハンドリングを一箇所に集約
    console.error('処理中にエラーが発生しました:', err);
    throw err; // 必要に応じて再スロー
  }
}

// ③ 呼び出し
getUserOrderDetails('user-123')
  .then(result => console.log('全データ取得完了:', result))
  .catch(err => console.error('最終エラー:', err));
```

---

## 並列処理できる場合は Promise.all を活用

```javascript
async function getUserOrderDetails(userId) {
  try {
    const user = await getUserAsync(userId);

    // 依存関係がない処理は並列実行で高速化！
    const [orders, profile] = await Promise.all([
      getOrdersAsync(user.id),
      getProfileAsync(user.id),  // 並列で取得
    ]);

    const details = await getOrderDetailsAsync(orders[0].id);
    const product = await getProductAsync(details.productId);

    return { user, orders, profile, details, product };

  } catch (err) {
    console.error('エラー:', err);
    throw err;
  }
}
```

---

## 比較まとめ

| 観点 | コールバック地獄 | async/await |
|------|----------------|-------------|
| **可読性** | ネストが深くつらい 😱 | フラットで読みやすい 😊 |
| **エラー処理** | 各階層で個別に必要 | `try/catch` 一箇所でOK |
| **デバッグ** | スタックトレースが追いにくい | 通常のコードと同様に追える |
| **並列処理** | 複雑になりがち | `Promise.all` で簡潔に書ける |
| **戻り値** | コールバック内でしか使えない | `return` で値を返せる |

> **ポイント:** 既存のコールバックAPIは `new Promise()` でラップすれば  
> `util.promisify`（Node.js）を使うとさらに簡単にPromise化できます。

```javascript
const { promisify } = require('util');
const getUserAsync = promisify(getUser); // これだけでOK！
```

