## コールバック地獄 → async/await

### Before（地獄）

```javascript
getUser(userId, function(err, user) {
  if (err) {
    handleError(err);
    return;
  }
  getOrders(user.id, function(err, orders) {
    if (err) {
      handleError(err);
      return;
    }
    getOrderDetails(orders[0].id, function(err, details) {
      if (err) {
        handleError(err);
        return;
      }
      renderPage(user, orders, details, function(err, html) {
        if (err) {
          handleError(err);
          return;
        }
        console.log(html);
      });
    });
  });
});
```

### After（async/await）

```javascript
async function loadPage(userId) {
  try {
    const user    = await getUser(userId);
    const orders  = await getOrders(user.id);
    const details = await getOrderDetails(orders[0].id);
    const html    = await renderPage(user, orders, details);
    console.log(html);
  } catch (err) {
    handleError(err);
  }
}

loadPage(userId);
```

---

### 並列実行できる場合は `Promise.all` 使え

依存関係ない処理を逐次awaitするのは無駄。

```javascript
// 悪い（合計待機時間 = A + B + C）
const a = await fetchA();
const b = await fetchB();
const c = await fetchC();

// 良い（合計待機時間 = max(A, B, C)）
const [a, b, c] = await Promise.all([fetchA(), fetchB(), fetchC()]);
```

---

### コールバック関数をPromise化する手順

既存コールバックAPIをasync/awaitで使うには `util.promisify` か手動ラップ。

```javascript
// Node.js組み込み
const { promisify } = require('util');
const readFile = promisify(fs.readFile);

// 手動ラップ（コールバックが (err, result) 形式の場合）
function getUser(id) {
  return new Promise((resolve, reject) => {
    getUserCallback(id, (err, user) => {
      if (err) reject(err);
      else resolve(user);
    });
  });
}
```

---

### 要点まとめ

| 問題 | 解決 |
|------|------|
| ネスト深い | `await` で直列フラット化 |
| エラー処理バラバラ | `try/catch` 一か所に集約 |
| 並列処理遅い | `Promise.all` で同時実行 |
| 古いAPIがコールバック | `promisify` でラップ |

## コールバック地獄 → async/await

### Before（コールバック地獄）

```javascript
getUser(userId, function(err, user) {
  if (err) {
    handleError(err);
    return;
  }
  getOrders(user.id, function(err, orders) {
    if (err) {
      handleError(err);
      return;
    }
    getOrderDetails(orders[0].id, function(err, details) {
      if (err) {
        handleError(err);
        return;
      }
      updateInventory(details.items, function(err, result) {
        if (err) {
          handleError(err);
          return;
        }
        console.log("完了:", result);
      });
    });
  });
});
```

### After（async/await）

```javascript
async function processOrder(userId) {
  try {
    const user    = await getUser(userId);
    const orders  = await getOrders(user.id);
    const details = await getOrderDetails(orders[0].id);
    const result  = await updateInventory(details.items);
    console.log("完了:", result);
  } catch (err) {
    handleError(err);
  }
}

processOrder(userId);
```

---

## 並列実行できるなら Promise.all

依存関係ない処理を直列にすると遅い。

```javascript
// ❌ 遅い：順番に待つ（合計時間 = A + B + C）
const a = await fetchA();
const b = await fetchB();
const c = await fetchC();

// ✅ 速い：並列実行（合計時間 = max(A, B, C)）
const [a, b, c] = await Promise.all([fetchA(), fetchB(), fetchC()]);
```

---

## エラー処理パターン

### 1. try/catch（シンプル）
```javascript
try {
  const data = await fetchData();
} catch (err) {
  // 全エラーここに落ちる
}
```

### 2. 個別エラー処理したい場合
```javascript
async function safe(promise) {
  try {
    const data = await promise;
    return [null, data];
  } catch (err) {
    return [err, null];
  }
}

const [err, user] = await safe(getUser(userId));
if (err) { /* ユーザー取得失敗だけ処理 */ }
```

### 3. finally（必ず実行）
```javascript
async function fetchWithLoading() {
  setLoading(true);
  try {
    return await fetchData();
  } finally {
    setLoading(false); // 成功・失敗どちらでも実行
  }
}
```

---

## よくある罠

| 罠 | 問題 | 修正 |
|----|------|------|
| `async` なし関数で `await` | SyntaxError | 関数に `async` 付ける |
| `forEach` 内で `await` | 待たない | `for...of` に変える |
| `await` 忘れ | Promise返る | `await` 付ける |

```javascript
// ❌ forEachはawaitを無視する
items.forEach(async (item) => {
  await process(item); // 待たない！
});

// ✅ for...ofなら順番に待つ
for (const item of items) {
  await process(item);
}

// ✅ 並列でいいなら
await Promise.all(items.map(item => process(item)));
```

