# React Error Boundary の実装

## 1. クラスコンポーネントによる基本実装

```tsx
// components/ErrorBoundary.tsx
import React, { Component, ErrorInfo, ReactNode } from 'react';

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null,
    };
  }

  // エラーが発生したときにstateを更新する
  static getDerivedStateFromError(error: Error): Partial<State> {
    return { hasError: true, error };
  }

  // エラーログを記録する
  componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    console.error('Error caught by ErrorBoundary:', error, errorInfo);
    this.setState({ errorInfo });

    // 外部エラーログサービスへの送信
    this.props.onError?.(error, errorInfo);
  }

  // エラー状態をリセットする
  handleReset = (): void => {
    this.setState({
      hasError: false,
      error: null,
      errorInfo: null,
    });
  };

  render(): ReactNode {
    if (this.state.hasError) {
      // カスタムfallbackが指定されている場合はそれを表示
      if (this.props.fallback) {
        return this.props.fallback;
      }

      // デフォルトのエラーUI
      return (
        <div style={styles.container}>
          <h2 style={styles.title}>⚠️ エラーが発生しました</h2>
          <p style={styles.message}>
            {this.state.error?.message || '予期しないエラーが発生しました'}
          </p>
          {process.env.NODE_ENV === 'development' && (
            <details style={styles.details}>
              <summary>詳細情報</summary>
              <pre style={styles.pre}>
                {this.state.error?.stack}
                {'\n\nComponent Stack:'}
                {this.state.errorInfo?.componentStack}
              </pre>
            </details>
          )}
          <button style={styles.button} onClick={this.handleReset}>
            再試行する
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    padding: '24px',
    margin: '16px',
    border: '1px solid #f5c6cb',
    borderRadius: '8px',
    backgroundColor: '#fff5f5',
    textAlign: 'center',
  },
  title: {
    color: '#c53030',
    fontSize: '20px',
    marginBottom: '12px',
  },
  message: {
    color: '#742a2a',
    marginBottom: '16px',
  },
  details: {
    textAlign: 'left',
    marginBottom: '16px',
  },
  pre: {
    overflow: 'auto',
    padding: '12px',
    backgroundColor: '#1a202c',
    color: '#e2e8f0',
    borderRadius: '4px',
    fontSize: '12px',
  },
  button: {
    padding: '8px 24px',
    backgroundColor: '#3182ce',
    color: 'white',
    border: 'none',
    borderRadius: '4px',
    cursor: 'pointer',
    fontSize: '16px',
  },
};

export default ErrorBoundary;
```

---

## 2. カスタムフックと組み合わせた実装

```tsx
// hooks/useErrorHandler.ts
import { useState, useCallback } from 'react';

interface UseErrorHandlerReturn {
  error: Error | null;
  setError: (error: Error | null) => void;
  resetError: () => void;
  handleError: (error: unknown) => void;
}

export const useErrorHandler = (): UseErrorHandlerReturn => {
  const [error, setError] = useState<Error | null>(null);

  const resetError = useCallback(() => setError(null), []);

  const handleError = useCallback((err: unknown) => {
    if (err instanceof Error) {
      setError(err);
    } else {
      setError(new Error(String(err)));
    }
  }, []);

  return { error, setError, resetError, handleError };
};
```

---

## 3. 高階コンポーネント (HOC) パターン

```tsx
// components/withErrorBoundary.tsx
import React, { ComponentType } from 'react';
import ErrorBoundary from './ErrorBoundary';

interface WithErrorBoundaryOptions {
  fallback?: React.ReactNode;
  onError?: (error: Error, errorInfo: React.ErrorInfo) => void;
}

function withErrorBoundary<T extends object>(
  WrappedComponent: ComponentType<T>,
  options: WithErrorBoundaryOptions = {}
): ComponentType<T> {
  const displayName =
    WrappedComponent.displayName || WrappedComponent.name || 'Component';

  const ComponentWithErrorBoundary = (props: T) => (
    <ErrorBoundary fallback={options.fallback} onError={options.onError}>
      <WrappedComponent {...props} />
    </ErrorBoundary>
  );

  ComponentWithErrorBoundary.displayName = `withErrorBoundary(${displayName})`;
  return ComponentWithErrorBoundary;
}

export default withErrorBoundary;
```

---

## 4. 実際の使用例

```tsx
// App.tsx
import React from 'react';
import ErrorBoundary from './components/ErrorBoundary';
import withErrorBoundary from './components/withErrorBoundary';

// ─── エラーを発生させるコンポーネント（テスト用）───
const BuggyComponent: React.FC<{ shouldThrow: boolean }> = ({ shouldThrow }) => {
  if (shouldThrow) {
    throw new Error('テスト用のエラーが発生しました！');
  }
  return <p>正常に動作しています ✅</p>;
};

// ─── カスタムfallbackコンポーネント ───
const CustomFallback: React.FC = () => (
  <div style={{ padding: 16, background: '#fffbeb', border: '1px solid #f6e05e' }}>
    <h3>😢 このセクションは現在利用できません</h3>
    <p>しばらくしてからもう一度お試しください。</p>
  </div>
);

// ─── HOCパターンの使用 ───
const SafeBuggyComponent = withErrorBoundary(BuggyComponent, {
  fallback: <CustomFallback />,
  onError: (error, info) => {
    // Sentry などへのエラー送信
    console.log('Error reported:', error.message);
  },
});

// ─── エラーログサービスへの送信 ───
const handleError = (error: Error, errorInfo: React.ErrorInfo): void => {
  // 例: Sentry.captureException(error, { extra: errorInfo });
  console.error('Global Error Handler:', { error, errorInfo });
};

// ─── App コンポーネント ───
const App: React.FC = () => {
  return (
    <div>
      {/* パターン1: 直接ラップ */}
      <ErrorBoundary
        fallback={<CustomFallback />}
        onError={handleError}
      >
        <BuggyComponent shouldThrow={false} />
      </ErrorBoundary>

      {/* パターン2: HOCを使用 */}
      <SafeBuggyComponent shouldThrow={true} />

      {/* パターン3: ネストした ErrorBoundary */}
      <ErrorBoundary onError={handleError}>
        <h2>セクション1</h2>
        <ErrorBoundary fallback={<p>セクション内エラー</p>}>
          <BuggyComponent shouldThrow={true} />
        </ErrorBoundary>
        <p>このコンテンツは表示されます</p>
      </ErrorBoundary>
    </div>
  );
};

export default App;
```

---

## 5. ポイントまとめ

| 項目 | 説明 |
|------|------|
| `getDerivedStateFromError` | エラー発生時にstateを更新し、フォールバックUIを表示 |
| `componentDidCatch` | エラーログの記録・外部サービスへの送信 |
| `fallback` prop | カスタムエラーUIを柔軟に差し替え可能 |
| `onError` prop | Sentry等の外部ログサービスと連携 |
| HOCパターン | 既存コンポーネントをラップして再利用性を向上 |
| ネスト | 影響範囲を局所化し、部分的なエラーに対応 |

> ⚠️ **注意**: Error Boundaryは以下のエラーを**キャッチできません**
> - イベントハンドラ内のエラー
> - 非同期処理（setTimeout, fetch など）
> - サーバーサイドレンダリング
> - Error Boundary 自身のエラー

# React Error Boundary の実装

## 1. クラスコンポーネントによる基本実装

```tsx
// components/ErrorBoundary.tsx
import React, { Component, ErrorInfo, ReactNode } from 'react';

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null,
    };
  }

  // エラーが発生したときにstateを更新する
  static getDerivedStateFromError(error: Error): Partial<State> {
    return { hasError: true, error };
  }

  // エラーのログ記録などの副作用を実行する
  componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    console.error('ErrorBoundary caught an error:', error, errorInfo);
    this.setState({ errorInfo });

    // 外部エラーログサービスへの送信（例: Sentry）
    this.props.onError?.(error, errorInfo);
  }

  // エラー状態をリセットする
  handleReset = (): void => {
    this.setState({
      hasError: false,
      error: null,
      errorInfo: null,
    });
  };

  render(): ReactNode {
    const { hasError, error, errorInfo } = this.state;
    const { children, fallback } = this.props;

    if (hasError) {
      // カスタムfallbackが指定されている場合はそれを表示
      if (fallback) return fallback;

      // デフォルトのエラーUI
      return (
        <div style={styles.container}>
          <h2 style={styles.title}>⚠️ エラーが発生しました</h2>
          <p style={styles.message}>{error?.message}</p>
          {process.env.NODE_ENV === 'development' && (
            <details style={styles.details}>
              <summary>詳細情報（開発環境のみ）</summary>
              <pre style={styles.pre}>
                {error?.stack}
                {errorInfo?.componentStack}
              </pre>
            </details>
          )}
          <button style={styles.button} onClick={this.handleReset}>
            🔄 再試行
          </button>
        </div>
      );
    }

    return children;
  }
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    padding: '2rem',
    margin: '1rem',
    border: '1px solid #ff4444',
    borderRadius: '8px',
    backgroundColor: '#fff5f5',
    textAlign: 'center',
  },
  title: {
    color: '#cc0000',
    fontSize: '1.5rem',
  },
  message: {
    color: '#555',
    marginBottom: '1rem',
  },
  details: {
    textAlign: 'left',
    marginBottom: '1rem',
  },
  pre: {
    backgroundColor: '#f4f4f4',
    padding: '1rem',
    overflow: 'auto',
    fontSize: '0.8rem',
    borderRadius: '4px',
  },
  button: {
    padding: '0.5rem 1.5rem',
    backgroundColor: '#0070f3',
    color: 'white',
    border: 'none',
    borderRadius: '4px',
    cursor: 'pointer',
    fontSize: '1rem',
  },
};

export default ErrorBoundary;
```

---

## 2. カスタムフック（React 18以降向け）

```tsx
// hooks/useErrorBoundary.ts
import { useState, useCallback } from 'react';

interface UseErrorBoundaryReturn {
  showBoundary: (error: Error) => void;
}

// 関数コンポーネント内から意図的にエラーをスローするためのフック
export const useErrorBoundary = (): UseErrorBoundaryReturn => {
  const [, setState] = useState<null>(null);

  const showBoundary = useCallback((error: Error) => {
    setState(() => {
      throw error;
    });
  }, []);

  return { showBoundary };
};
```

---

## 3. HOC（高階コンポーネント）版

```tsx
// hoc/withErrorBoundary.tsx
import React, { ComponentType } from 'react';
import ErrorBoundary from '../components/ErrorBoundary';

interface WithErrorBoundaryOptions {
  fallback?: React.ReactNode;
  onError?: (error: Error, errorInfo: React.ErrorInfo) => void;
}

function withErrorBoundary<P extends object>(
  WrappedComponent: ComponentType<P>,
  options: WithErrorBoundaryOptions = {}
): ComponentType<P> {
  const displayName =
    WrappedComponent.displayName || WrappedComponent.name || 'Component';

  const ComponentWithErrorBoundary = (props: P) => (
    <ErrorBoundary fallback={options.fallback} onError={options.onError}>
      <WrappedComponent {...props} />
    </ErrorBoundary>
  );

  ComponentWithErrorBoundary.displayName = `withErrorBoundary(${displayName})`;
  return ComponentWithErrorBoundary;
}

export default withErrorBoundary;
```

---

## 4. 使用例

```tsx
// App.tsx
import React from 'react';
import ErrorBoundary from './components/ErrorBoundary';
import withErrorBoundary from './hoc/withErrorBoundary';
import { useErrorBoundary } from './hooks/useErrorBoundary';

// ─────────────────────────────────────────
// エラーを発生させるサンプルコンポーネント
// ─────────────────────────────────────────
const BuggyComponent: React.FC = () => {
  const [shouldThrow, setShouldThrow] = React.useState(false);

  if (shouldThrow) {
    throw new Error('意図的なエラーが発生しました！');
  }

  return (
    <div>
      <p>正常なコンポーネント</p>
      <button onClick={() => setShouldThrow(true)}>エラーを発生させる</button>
    </div>
  );
};

// ─────────────────────────────────────────
// フックを使ったコンポーネント
// ─────────────────────────────────────────
const AsyncComponent: React.FC = () => {
  const { showBoundary } = useErrorBoundary();

  const fetchData = async () => {
    try {
      const response = await fetch('/api/data');
      if (!response.ok) throw new Error('APIエラー');
    } catch (error) {
      showBoundary(error as Error); // Error Boundaryに委譲
    }
  };

  return <button onClick={fetchData}>データ取得</button>;
};

// HOCで包んだコンポーネント
const SafeComponent = withErrorBoundary(BuggyComponent, {
  fallback: <p>このコンポーネントは壊れています。</p>,
});

// ─────────────────────────────────────────
// メインApp
// ─────────────────────────────────────────
const App: React.FC = () => {
  const handleError = (error: Error) => {
    // Sentryなどに送信
    console.error('Global error captured:', error);
  };

  return (
    <div>
      {/* ① ラッパーとして使う */}
      <ErrorBoundary onError={handleError}>
        <BuggyComponent />
      </ErrorBoundary>

      {/* ② カスタムfallbackを渡す */}
      <ErrorBoundary fallback={<p>💥 カスタムエラー画面</p>}>
        <BuggyComponent />
      </ErrorBoundary>

      {/* ③ HOC版 */}
      <SafeComponent />

      {/* ④ フック版（非同期エラー対応） */}
      <ErrorBoundary>
        <AsyncComponent />
      </ErrorBoundary>
    </div>
  );
};

export default App;
```

---

## 5. ポイントまとめ

| 項目 | 内容 |
|---|---|
| **`getDerivedStateFromError`** | エラー発生時にstateを更新しフォールバックUIを描画 |
| **`componentDidCatch`** | ログ送信など副作用処理に使用 |
| **`useErrorBoundary`** | 非同期処理のエラーをBoundaryに伝播させる |
| **HOC版** | 既存コンポーネントを変更せず安全にラップ |
| **注意点** | イベントハンドラ・非同期処理のエラーは**自動でキャッチされない** |

> **💡 ライブラリ活用**  
> [react-error-boundary](https://github.com/bvaughn/react-error-boundary) を使うと、これらの機能がすぐに利用可能です。

# React Error Boundary の実装

## 1. 基本的な Error Boundary クラスコンポーネント

```tsx
// components/ErrorBoundary.tsx
import React, { Component, ErrorInfo, ReactNode } from 'react';

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null,
    };
  }

  // エラー発生時にstateを更新
  static getDerivedStateFromError(error: Error): Partial<State> {
    return { hasError: true, error };
  }

  // エラーのログ記録
  componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    console.error('ErrorBoundary caught an error:', error, errorInfo);
    this.setState({ errorInfo });
    this.props.onError?.(error, errorInfo);
  }

  // エラー状態をリセット
  handleReset = (): void => {
    this.setState({
      hasError: false,
      error: null,
      errorInfo: null,
    });
  };

  render(): ReactNode {
    if (this.state.hasError) {
      // カスタムfallbackがあればそれを表示
      if (this.props.fallback) {
        return this.props.fallback;
      }

      // デフォルトのエラーUI
      return (
        <DefaultErrorFallback
          error={this.state.error}
          errorInfo={this.state.errorInfo}
          onReset={this.handleReset}
        />
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;
```

