## 3. カスタムフック（React 18以降向け）

```tsx
// hooks/useErrorBoundary.ts
import { useState, useCallback } from 'react';

interface UseErrorBoundaryReturn {
  showBoundary: (error: Error) => void;
}

// Error Boundaryに手動でエラーを渡すフック
export const useErrorBoundary = (): UseErrorBoundaryReturn => {
  const [, setState] = useState<null>(null);

  const showBoundary = useCallback((error: Error) => {
    setState(() => {
      throw error;
    });
  }, []);

  return { showBoundary };
};
```

