```

```jsx
import { ErrorBoundary } from 'react-error-boundary';

function FallbackComponent({ error, resetErrorBoundary }) {
  return (
    <div>
      <p>エラー: {error.message}</p>
      <button onClick={resetErrorBoundary}>リセット</button>
    </div>
  );
}

<ErrorBoundary
  FallbackComponent={FallbackComponent}
  onError={(error, info) => logToService(error, info)}
  onReset={() => { /* リセット時の処理 */ }}
>
  <App />
</ErrorBoundary>
```

---

## 注意点

| 制限 | 内容 |
|------|------|
| **捕捉できない** | イベントハンドラ内エラー、非同期処理（`async/await`）、SSR |
| **クラス必須** | Hooks だけでは Error Boundary 作れない（React 19 以降も同様） |
| **粒度** | 大きな単位より機能単位で囲うと障害範囲を限定できる |

イベントハンドラ内エラーは通常の `try/catch` で処理。

## Error Boundary 実装

### 基本実装（クラスコンポーネント必須）

```jsx
import React from 'react';

class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null, errorInfo: null };
  }

  // エラー発生時にstateを更新
  static getDerivedStateFromError(error) {
    return { hasError: true, error };
  }

  // ログ送信などの副作用処理
  componentDidCatch(error, errorInfo) {
    this.setState({ errorInfo });
    // Sentry等に送信する場合はここ
    // logErrorToService(error, errorInfo);
    console.error('ErrorBoundary caught:', error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return this.props.fallback ?? (
        <div>
          <h2>エラーが発生しました</h2>
          <details>
            <summary>詳細</summary>
            <pre>{this.state.error?.toString()}</pre>
            <pre>{this.state.errorInfo?.componentStack}</pre>
          </details>
          <button onClick={() => this.setState({ hasError: false, error: null, errorInfo: null })}>
            リセット
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;
```

---

### 使い方

```jsx
// アプリ全体を囲む
<ErrorBoundary>
  <App />
</ErrorBoundary>

// カスタムfallback指定
<ErrorBoundary fallback={<p>読み込み失敗</p>}>
  <SomeComponent />
</ErrorBoundary>

// 細かい粒度で囲む（推奨）
function Dashboard() {
  return (
    <div>
      <ErrorBoundary fallback={<p>ウィジェット読込エラー</p>}>
        <Widget />
      </ErrorBoundary>
      <ErrorBoundary fallback={<p>チャート読込エラー</p>}>
        <Chart />
      </ErrorBoundary>
    </div>
  );
}
```

---

### react-error-boundary ライブラリ使う場合（実務推奨）

```bash
npm install react-error-boundary
```

```jsx
