function ErrorFallback({ error, resetErrorBoundary }) {
  return (
    <div>
      <p>エラー: {error.message}</p>
      <button onClick={resetErrorBoundary}>再試行</button>
    </div>
  );
}

function App() {
  return (
    <ErrorBoundary
      FallbackComponent={ErrorFallback}
      onError={(error, info) => console.error(error, info)}
      onReset={() => {/* 状態リセット処理 */}}
    >
      <MyComponent />
    </ErrorBoundary>
  );
}
```

---

### 注意点

| 捕捉できる | 捕捉できない |
|---|---|
| renderメソッド内のエラー | イベントハンドラ内のエラー |
| ライフサイクルメソッドのエラー | 非同期処理（async/await）のエラー |
| 子コンポーネントのエラー | SSR のエラー |

イベントハンドラのエラーは通常の `try/catch` で処理。

