## 🔬 Step 4: よくあるメモリリークのパターンと対策

### ❌ パターン1: グローバル変数への蓄積

```javascript
// Bad: 配列がどんどん増える
const cache = [];
app.get('/data', (req, res) => {
  cache.push({ data: req.body, time: Date.now() }); // 削除されない！
  res.json({ ok: true });
});

// Good: サイズ制限を設ける
const MAX_CACHE_SIZE = 1000;
const cache = [];
app.get('/data', (req, res) => {
  cache.push({ data: req.body, time: Date.now() });
  if (cache.length > MAX_CACHE_SIZE) {
    cache.shift(); // 古いものを削除
  }
  res.json({ ok: true });
});

// Better: Map + TTL を使う
const cache = new Map();
function setCache(key, value, ttl = 60000) {
  cache.set(key, { value, expiry: Date.now() + ttl });
  setTimeout(() => cache.delete(key), ttl); // 自動削除
}
```

### ❌ パターン2: イベントリスナーの登録し過ぎ

```javascript
// Bad: リスナーが増え続ける
function setupHandler(emitter) {
  emitter.on('data', (data) => {
    // 処理
  });
}
// setupHandlerが呼ばれるたびにリスナーが追加される

// Good: once を使うか、明示的に削除
function setupHandler(emitter) {
  const handler = (data) => {
    // 処理
    emitter.off('data', handler); // 使い終わったら削除
  };
  emitter.on('data', handler);
}

// リスナー数の上限を確認・設定
emitter.setMaxListeners(20);
console.log(emitter.listenerCount('data')); // リスナー数を確認
```

### ❌ パターン3: クロージャによるリーク

```javascript
// Bad: 大きなデータがクロージャに捕捉される
function createHandler() {
  const bigData = new Array(1000000).fill('data'); // 大きなデータ

  return function handler(req, res) {
    // bigData を使わないのに参照が残る
    res.json({ ok: true });
  };
}

// Good: 必要なデータだけを保持
function createHandler() {
  const bigData = new Array(1000000).fill('data');
  const processedData = bigData.length; // 必要な情報だけ抽出
  // bigData はここで GC 対象になる

  return function handler(req, res) {
    res.json({ count: processedData });
  };
}
```

### ❌ パターン4: タイマーのクリア漏れ

```javascript
// Bad: clearInterval されない
class DataPoller {
  start() {
    this.timer = setInterval(() => {
      this.fetchData();
    }, 1000);
  }
  // stop() がない！
}

// Good: 必ず停止メソッドを用意
class DataPoller {
  start() {
    this.timer = setInterval(() => {
      this.fetchData();
    }, 1000);
  }

  stop() {
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }
}
```

### ❌ パターン5: WeakMap/WeakSet を活用していない

```javascript
// Bad: オブジェクトへの強参照
const metaData = new Map();
function process(obj) {
  metaData.set(obj, { processed: true }); // obj が消えても Map に残る
}

// Good: WeakMap で弱参照
const metaData = new WeakMap();
function process(obj) {
  metaData.set(obj, { processed: true }); // obj が GC されたら自動削除
}
```

---

## 📈 Step 5: 負荷テストと組み合わせて調査

