# APIレート制限の実装方法

## 主なアルゴリズム

| アルゴリズム | 特徴 |
|------------|------|
| **Fixed Window** | 固定時間窓でカウント。シンプルだが境界問題あり |
| **Sliding Window** | より正確。境界問題を解決 |
| **Token Bucket** | バースト許容。柔軟性が高い |
| **Leaky Bucket** | 一定レートで処理。安定性重視 |

---

## 実装例

### 1. Fixed Window（Redis使用・Node.js）

```javascript
const redis = require('redis');
const client = redis.createClient();

async function rateLimiter(userId, limit = 100, windowSec = 60) {
  const key = `rate:${userId}:${Math.floor(Date.now() / 1000 / windowSec)}`;

  const count = await client.incr(key);

  if (count === 1) {
    await client.expire(key, windowSec); // 初回のみTTL設定
  }

  if (count > limit) {
    throw new Error('Rate limit exceeded');
  }

  return { count, limit, remaining: limit - count };
}
```

### 2. Sliding Window（Redis + Sorted Set）

```javascript
async function slidingWindowLimiter(userId, limit = 100, windowMs = 60000) {
  const key = `rate:sliding:${userId}`;
  const now = Date.now();
  const windowStart = now - windowMs;

  // パイプラインで原子的に実行
  await client.zRemRangeByScore(key, 0, windowStart); // 古いリクエスト削除
  const count = await client.zCard(key);

  if (count >= limit) {
    throw new Error('Rate limit exceeded');
  }

  await client.zAdd(key, { score: now, value: `${now}-${Math.random()}` });
  await client.expire(key, Math.ceil(windowMs / 1000));

  return { count: count + 1, remaining: limit - count - 1 };
}
```

### 3. Token Bucket

```javascript
class TokenBucket {
  constructor(capacity, refillRate) {
    this.capacity = capacity;    // 最大トークン数
    this.tokens = capacity;      // 現在のトークン
    this.refillRate = refillRate; // 秒あたりの補充数
    this.lastRefill = Date.now();
  }

  consume(tokens = 1) {
    this.refill();

    if (this.tokens < tokens) {
      return false; // リクエスト拒否
    }

    this.tokens -= tokens;
    return true;
  }

  refill() {
    const now = Date.now();
    const elapsed = (now - this.lastRefill) / 1000;
    this.tokens = Math.min(
      this.capacity,
      this.tokens + elapsed * this.refillRate
    );
    this.lastRefill = now;
  }
}
```

### 4. Express ミドルウェアとして適用

```javascript
const express = require('express');
const app = express();

function rateLimitMiddleware(limit, windowSec) {
  return async (req, res, next) => {
    const userId = req.user?.id || req.ip;

    try {
      const result = await rateLimiter(userId, limit, windowSec);

      // レート制限情報をヘッダーに付与（標準的な実装）
      res.set({
        'X-RateLimit-Limit': limit,
        'X-RateLimit-Remaining': result.remaining,
        'X-RateLimit-Reset': Math.floor(Date.now() / 1000) + windowSec,
      });

      next();
    } catch (error) {
      res.status(429).json({
        error: 'Too Many Requests',
        retryAfter: windowSec,
      });
    }
  };
}

// 適用例
app.use('/api/', rateLimitMiddleware(100, 60));        // 全体
app.use('/api/login', rateLimitMiddleware(5, 300));    // ログインは厳しく
```

---

## 既存ライブラリを使う場合

```bash
# Node.js
npm install express-rate-limit rate-limiter-flexible

# Python
pip install slowapi limits
```

```javascript
// express-rate-limit（シンプル版）
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 60 * 1000,
  max: 100,
  standardHeaders: true,
  message: { error: 'Too many requests' },
});

app.use('/api', limiter);
```

---

## ベストプラクティス

```
✅ Redisで状態管理（スケーラブル）
✅ 適切なHTTPヘッダーを返す（X-RateLimit-*）
✅ 429ステータスコードを使用
✅ Retry-After ヘッダーで再試行時間を通知
✅ エンドポイントごとに異なる制限を設定
✅ IPだけでなくユーザーIDでも制限
⚠️ 分散環境ではRedisなど共有ストレージが必須
```

---

## Python版（FastAPI）

```python
from slowapi import Limiter
from slowapi.util import get_remote_address

limiter = Limiter(key_func=get_remote_address)

@app.get("/api/data")
@limiter.limit("100/minute")
async def get_data(request: Request):
    return {"data": "..."}
```

どの言語・フレームワークで実装したいか教えていただければ、より詳しく説明します！

caveman_texts:
# APIレート制限の実装

## 主要アルゴリズム

| アルゴリズム | 特徴 | 用途 |
|------------|------|------|
| **固定ウィンドウ** | シンプル、境界問題あり | 基本的な制限 |
| **スライディングウィンドウ** | 正確、メモリ使用多 | 精度重視 |
| **トークンバケット** | バースト許容、柔軟 | API一般 |
| **リーキーバケット** | 均一レート、キュー管理 | 安定スループット |

---

## 実装例

### 1. 固定ウィンドウ（Redis + Node.js）

```javascript
const redis = require('redis');
const client = redis.createClient();

async function fixedWindowRateLimit(userId, limit = 100, windowSec = 60) {
  const key = `ratelimit:${userId}:${Math.floor(Date.now() / 1000 / windowSec)}`;

  const count = await client.incr(key);
  if (count === 1) {
    await client.expire(key, windowSec);
  }

  if (count > limit) {
    return { allowed: false, remaining: 0, resetIn: windowSec };
  }

  return { allowed: true, remaining: limit - count };
}
```

### 2. スライディングウィンドウ（Redis Sorted Set）

```javascript
async function slidingWindowRateLimit(userId, limit = 100, windowMs = 60000) {
  const key = `ratelimit:sliding:${userId}`;
  const now = Date.now();
  const windowStart = now - windowMs;

  await client.zRemRangeByScore(key, 0, windowStart); // 古いエントリ削除
  const count = await client.zCard(key);

  if (count >= limit) {
    return { allowed: false, remaining: 0 };
  }

  await client.zAdd(key, { score: now, value: `${now}-${Math.random()}` });
  await client.expire(key, Math.ceil(windowMs / 1000));

  return { allowed: true, remaining: limit - count - 1 };
}
```

### 3. トークンバケット

```javascript
async function tokenBucketRateLimit(userId, capacity = 100, refillRate = 10) {
  const key = `ratelimit:bucket:${userId}`;
  const now = Date.now() / 1000;

  const data = await client.hGetAll(key);
  let tokens = parseFloat(data.tokens ?? capacity);
  let lastRefill = parseFloat(data.lastRefill ?? now);

  // トークン補充
  const elapsed = now - lastRefill;
  tokens = Math.min(capacity, tokens + elapsed * refillRate);

  if (tokens < 1) {
    return { allowed: false, remaining: 0 };
  }

  tokens -= 1;
  await client.hSet(key, { tokens, lastRefill: now });
  await client.expire(key, 3600);

  return { allowed: true, remaining: Math.floor(tokens) };
}
```

---

## Expressミドルウェア化

```javascript
function rateLimitMiddleware(options = {}) {
  const { limit = 100, windowSec = 60 } = options;

  return async (req, res, next) => {
    const userId = req.user?.id ?? req.ip; // 識別子

    const result = await fixedWindowRateLimit(userId, limit, windowSec);

    // 標準ヘッダー付与
    res.set({
      'X-RateLimit-Limit': limit,
      'X-RateLimit-Remaining': result.remaining,
      'X-RateLimit-Reset': result.resetIn ?? windowSec,
    });

    if (!result.allowed) {
      return res.status(429).json({
        error: 'Too Many Requests',
        retryAfter: result.resetIn,
      });
    }

    next();
  };
}

// 使用例
app.use('/api/', rateLimitMiddleware({ limit: 100, windowSec: 60 }));
app.use('/api/auth/', rateLimitMiddleware({ limit: 10, windowSec: 60 })); // 厳しめ
```

---

## 重要な設計ポイント

**識別子の選択**
- 認証済み → `user_id`
- 未認証 → `IP`（注意: NATで複数ユーザー共有あり）
- API → `api_key`

**エンドポイント別に制限を分ける**
```
/auth/login    → 10回/分（ブルートフォース対策）
/api/general   → 1000回/時
/api/expensive → 10回/分
```

**レスポンスヘッダー**（RFC 6585準拠）
```
X-RateLimit-Limit: 100
X-RateLimit-Remaining: 42
X-RateLimit-Reset: 1693000000
Retry-After: 30   ← 429返す時
```

---

## ライブラリ使う場合

```bash
# Node.js
npm install express-rate-limit rate-limit-redis

# Python (FastAPI)
pip install slowapi
```

```javascript
// express-rate-limit + Redis（本番推奨）
const rateLimit = require('express-rate-limit');
const RedisStore = require('rate-limit-redis');

const limiter = rateLimit({
  windowMs: 60 * 1000,
  max: 100,
  store: new RedisStore({ client }),
  standardHeaders: true,
  legacyHeaders: false,
});
```

---

**本番チェックリスト**
- [ ] Redis使用（メモリ内だと複数サーバーで共有不可）
- [ ] エンドポイント別制限設定
- [ ] 429レスポンスに`Retry-After`ヘッダー
- [ ] レート制限ヒット時のログ・監視
- [ ] 信頼できるプロキシのIP取得設定（`trust proxy`）
